#!/usr/bin/env bash
# Phase 4 bench runner — current-main edition (uses the TOKENSPEED_MLA
# backend class instead of the rc14 env-var swap, and the BF16-KV patched
# K2.6 snapshot since the FP8 KV default crashes on the upstream NVRTC bug).
#
# Usage:
#   ./run_bench_v2.sh <config.yml> [<concurrency>] [<dataset.txt>]
#
# Defaults:
#   concurrency  → parsed from config filename (e.g. conc16 -> 16) or 1
#   dataset      → /scratch/runs/k2.6-spike/datasets/synth_<isl><osl>_<N>.txt,
#                  auto-generated by trtllm-bench prepare-dataset if missing.
#
# Differences from run_bench.sh:
#   - Selects backend via YAML attn_backend (TRTLLM | TOKENSPEED_MLA).
#     A sidecar YAML overrides per-variant. No more env-var swap.
#   - Defaults MODEL_PATH to the BF16-KV-patched snapshot; the FP8 KV path
#     in current main hits a JIT cubin compile bug regardless of backend.
#   - Adds PYTHONPATH=/workspace/TensorRT-LLM to shadow the rc14 install
#     with the current-main source tree (the bind-mounted /workspace/...).
#
# Spike-step-7 warning still applies — track whether trtllm-bench has the
# q_len_per_req = 1 - input_length regression on current main; if both
# variants fail with the same negative-shape error, fall back to the
# minimal_generate.py-based timing path.

set -euo pipefail

CONFIG="${1:?usage: run_bench_v2.sh <config.yml> [<concurrency>] [<dataset>]}"
[[ -f "$CONFIG" ]] || { echo "config not found: $CONFIG" >&2; exit 1; }
CONFIG_NAME="$(basename "$CONFIG" .yml)"

# Parse concurrency: explicit arg > parsed from filename > default 1.
CONC="${2:-}"
if [[ -z "$CONC" ]]; then
    if [[ "$CONFIG_NAME" =~ conc([0-9]+) ]]; then
        CONC="${BASH_REMATCH[1]}"
    else
        CONC=1
    fi
fi

# Parse ISL/OSL from filename for dataset auto-gen (e.g. 1k1k -> 1024/1024,
# 60k1k -> 61440/1024, 8k1k -> 8192/1024). Default 1k/1k.
ISL=1024; OSL=1024
if [[ "$CONFIG_NAME" =~ ([0-9]+)k([0-9]+)k ]]; then
    A="${BASH_REMATCH[1]}"; B="${BASH_REMATCH[2]}"
    case "$A" in 60) ISL=61440;; *) ISL=$((A*1024));; esac
    OSL=$((B*1024))
fi

CONTAINER="${CONTAINER:-tokenspeed-spike-k26}"
# BF16-KV patched snapshot. The default FP8 KV crashes on the upstream NVRTC
# bug whether you go via TRTLLM or TOKENSPEED_MLA → TRTLLM fallback.
MODEL_PATH="${MODEL_PATH:-/scratch/hf-cache-patched/k2.6-bf16kv}"
RUN_DIR="/scratch/runs/k2.6-spike/phase4-bench/$CONFIG_NAME"
NUM_REQ="${NUM_REQ:-$((CONC * 16))}"   # 16× concurrency for steady state

# TP parsed from filename (e.g. _tp4_ -> 4, _tp8_ -> 8); default 4.
TP=4
if [[ "$CONFIG_NAME" =~ _tp([0-9]+) ]]; then TP="${BASH_REMATCH[1]}"; fi
TP="${TP_OVERRIDE:-$TP}"

DEFAULT_DATASET="/scratch/runs/k2.6-spike/datasets/synth_${A:-1}k${B:-1}k_${NUM_REQ}.txt"
DATASET="${3:-$DEFAULT_DATASET}"

# Copy config into the bind-mounted scratch dir (host = container at
# /scratch/). docker cp doesn't work here because Docker's userns-remap
# rejects the chown to the host UID; use a direct host-side copy instead.
CFG_HOST="/home/scratch.fkhoubsirat_coreai/runs/k2.6-spike/configs/$CONFIG_NAME.yml"
CFG_IN_CTR="/scratch/runs/k2.6-spike/configs/$CONFIG_NAME.yml"
mkdir -p "$(dirname "$CFG_HOST")"
cp "$CONFIG" "$CFG_HOST"
chmod 666 "$CFG_HOST"
docker exec "$CONTAINER" mkdir -p "$RUN_DIR" "/scratch/runs/k2.6-spike/datasets"

# Make output dir writable by the userns-remapped container root.
chmod 777 "/home/scratch.fkhoubsirat_coreai/runs/k2.6-spike/phase4-bench" 2>/dev/null || true
chmod 777 "/home/scratch.fkhoubsirat_coreai/runs/k2.6-spike/phase4-bench/$CONFIG_NAME" 2>/dev/null || true
chmod 777 "/home/scratch.fkhoubsirat_coreai/runs/k2.6-spike/configs" 2>/dev/null || true

docker exec "$CONTAINER" bash -c "
    set -uo pipefail
    MODEL=$MODEL_PATH
    if [[ ! -d \"\$MODEL\" ]]; then
        echo 'ERROR: model snapshot dir \$MODEL not found' >&2
        exit 1
    fi
    echo \"[bench] config=$CONFIG_NAME conc=$CONC isl=$ISL osl=$OSL model=\$MODEL\"

    # Build sidecar configs that override attn_backend per variant.
    # These are passed to minimal_bench.py via --extra_llm_api_options. The
    # config also drops max_seq_len / max_num_tokens / tensor_parallel_size
    # because minimal_bench.py accepts them as CLI args; leaving them in
    # the YAML is OK (they're propagated to LLM()).
    BASE_CFG=$RUN_DIR/_config_base.yml
    TS_CFG=$RUN_DIR/_config_ts.yml
    sed 's/^attn_backend:.*/attn_backend: TRTLLM/' \"$CFG_IN_CTR\" > \"\$BASE_CFG\"
    sed 's/^attn_backend:.*/attn_backend: TOKENSPEED_MLA/' \"$CFG_IN_CTR\" > \"\$TS_CFG\"

    for VARIANT in base ts; do
        if [[ \$VARIANT == base ]]; then
            CFG=\$BASE_CFG
            BACKEND=TRTLLM
        else
            CFG=\$TS_CFG
            BACKEND=TOKENSPEED_MLA
        fi
        LOG=$RUN_DIR/\${VARIANT}.log

        echo \"[bench] running \$VARIANT (attn_backend=\$BACKEND) -> \$LOG\"
        # minimal_bench.py uses skip_tokenizer_init=True + token-ID prompts;
        # bypasses K2.6's broken AutoTokenizer setup that crashes trtllm-bench.
        PYTHONPATH=/workspace/TensorRT-LLM \
            python3 -u /workspace/TensorRT-LLM/.claude_docs/tokenspeed-kimik25/scripts/minimal_bench.py \
                --model_dir \"\$MODEL\" \
                --tp_size $TP \
                --isl $ISL --osl $OSL \
                --num_requests $NUM_REQ --concurrency $CONC \
                --extra_llm_api_options \"\$CFG\" \
                > \"\$LOG\" 2>&1 || {
                    echo \"  WARN: \$VARIANT failed; tail of log:\"
                    tail -25 \"\$LOG\"
                }
    done

    echo
    echo \"=== A/B summary ===\"
    for VARIANT in base ts; do
        LOG=$RUN_DIR/\${VARIANT}.log
        printf \"  %-4s  \" \"\$VARIANT\"
        if grep -qE 'Per User Output|Token Throughput|Time To First|Inter Token' \"\$LOG\"; then
            grep -E 'Per User Output|Token Throughput|Time To First|Inter Token' \"\$LOG\" \
                | tail -6 | tr '\\n' '|' | sed 's/|/  /g'
            echo
        else
            echo \"(no perf summary — likely failed)\"
        fi
    done
    echo \"Full logs in $RUN_DIR/{base,ts}.log\"
"
